{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek a tipping basket once the threshold is crossed"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer period (for example, 24 months)"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Applying the general cap and time limits to capacity and title is not acceptable for a 100% share acquisition."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "keep title/fundamental, tax, specific indemnities, fraud, deliberate concealment and other agreed carve-outs outside it or under separate caps."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Do not accept blanket data-room and public-register disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "replace blanket disclosure and constructive-knowledge defences with specific, fair disclosure and a narrow knowledge standard"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require a completion condition for effective written consent and satisfaction or waiver of all associated conditions, with evidence."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require Riverlark debt repayment and release as a completion deliverable."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "ensure the AUD 420,000 bonuses, supplier commitments and all debt-like amounts are expressly allocated under the price mechanics."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require pre-completion payment and a valid assignment/confirmation of all relevant IP and rights, including any necessary consents."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require prompt investigation and a complete report, preservation of evidence, appropriate containment/remediation and cooperation"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Require any agreed liability to be reflected in working capital, debt-like items or transaction expenses as appropriate"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject applying any limitation to all Claims by default; periods should be expressly tailored by claim type."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require customary title warranties and verify them independently."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not accept that these are “settled” merely because the Seller says the general regime applies."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

